DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM organizational_scope.scope LIMIT 1)
    OR EXISTS(SELECT 1 FROM organizational_scope.idempotency_record LIMIT 1) THEN
   RAISE EXCEPTION 'F13_P1_DOWN_REFUSES_DATA_LOSS';
 END IF;
END $$;
